INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Ireland';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Peppol + real-time reporting (hybrid)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Ireland''s exact technical specifications, reported-data fields, and penalty framework are still being finalised — confirm current requirements directly with Revenue before building an integration.', 'Ireland''s VAT Modernisation programme has moved from consultation to confirmed scope faster than most — Phase 1''s taxpayer criteria were locked down over two years before go-live.', 'Ireland''s direction is clear even if the last technical details aren''t locked — this is one clear step ahead of the UK''s still-open format question.', 'Ireland sits between the UK''s pure decentralised model and France or Poland''s full clearance model — invoices don''t need government pre-approval, but transaction data still flows to Revenue in real time. Ireland''s phased timeline and reporting model are firmly confirmed by Revenue — including who''s in Phase 1. The detailed technical specification (exact schema profile, API detail) is still being finalised alongside the Irish Peppol Authority; sections below are marked Confirmed or Pending technical spec accordingly.', 'There''s no self-assessment step here — Revenue tells you if you''re in Phase 1, not the other way around.', 'No penalty framework has been published yet — expect this alongside the detailed technical specifications ahead of Phase 1.' FROM countries WHERE name_en = 'Ireland';
